
const sanitizeHTML = (() => {
    if (window.trustedTypes && window.trustedTypes.createPolicy) {
        const policy = window.trustedTypes.createPolicy('dioco-policy', {
            createHTML: (value) => value,
        });

        return (value) => policy.createHTML(value);
    }

    return (value) => value;
})();

window.__SANITIZE_HTML__ = sanitizeHTML;

